const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let records=[],type='小說',tag='全部',current=null,fontSize=19,comicMode='連續',comicPage=0;
try{fontSize=Math.min(26,Math.max(16,+localStorage.getItem('41-font')||19))}catch{}
document.documentElement.style.setProperty('--font-size',fontSize+'px');
function published(){return records.filter(r=>r.published)}
function prose(body){return String(body||'').split(/\n\s*\n/).filter(Boolean).map(p=>`<p>${esc(p)}</p>`).join('')}
function openDialog(html){$('#dialogContent').innerHTML=html;$('#dialog').showModal()}
$('#closeDialog').onclick=()=>$('#dialog').close();
$('#dialog').addEventListener('click',e=>{if(e.target===$('#dialog'))$('#dialog').close()});
function updateCounts(){const n=published().filter(r=>r.type==='小說'&&!r.restricted).length;$('.tabs [data-type="小說"] span').textContent=String(n).padStart(2,'0');const samples=published().filter(r=>r.sample).length;$('.sample-note').textContent=samples?`目前收錄 ${published().length} 篇作品，其中 ${samples} 篇為示範內容。正式作品將陸續歸檔。`:`目前收錄 ${published().length} 篇作品。時間停留在他們還相信會永遠在一起的半年。`;const main=published().find(r=>r.mainComic);if(main){$('.availability').textContent=`${main.images.length} 頁 · 連續 / 單頁閱讀`}}
function render(){
 const query=$('#search').value.trim().toLowerCase();
 if(type==='人物'){
  const people=[{no:'01',name:'班傑明・灰郭肉',en:'BENJAMIN HUI GUO ROU',desc:'第一王子。王族與軍方的實權人物。',note:'同人設定：身高 210 cm。第四王子持有其私人宅邸出入權限。'},{no:'04',name:'切利多尼希・灰郭肉',en:'TSERRIEDNICH HUI GUO ROU',desc:'第四王子。第一王妃烏瑪之子，與第一王子同母。',note:'同人設定：身高 187 cm。關係欄位：哥哥。［疑似遭本人竄改］'}].filter(p=>(p.name+p.en+p.desc).toLowerCase().includes(query));
  $('#resultCount').textContent=`${people.length} PERSONNEL FILES`;$('#records').innerHTML=people.map(p=>`<article class="record"><span class="record-no">${p.no}</span><div><p class="eyebrow">PERSONNEL / SUBJECT ${p.no}</p><h3>${p.name}</h3><p class="record-summary">${p.en}<br>${p.desc}</p></div><button class="record-open" data-person="${p.no}">OPEN FILE ↗</button></article>`).join('')||'<div class="empty-state">沒有符合的資料。</div>';
  document.querySelectorAll('[data-person]').forEach(b=>b.onclick=()=>{let p=people.find(p=>p.no===b.dataset.person);openDialog(`<p class="eyebrow">PERSONNEL RECORD / SUBJECT ${p.no}</p><h2>${p.name}</h2><p>${p.desc}</p><p>${p.note}</p><p class="tiny">RELATIONSHIP : <span title="全國上下都知道。">████████</span></p><p>此處分別標示原作身分與同人設定，非官方角色資料庫。</p>`)});return;
 }
 const items=published().filter(r=>type==='限制'?r.restricted:r.type===type&&!r.restricted).filter(r=>tag==='全部'||r.tags.includes(tag)).filter(r=>(r.title+r.officialTitle+r.summary+r.body+r.tags.join('')).toLowerCase().includes(query));
 $('#resultCount').textContent=`${String(items.length).padStart(2,'0')} FILES FOUND`;
 $('#records').innerHTML=items.map((r,i)=>`<article class="record"><span class="record-no">${String(i+1).padStart(2,'0')}</span><div><p class="eyebrow">${r.type==='小說'?'INCIDENT':'FILE'} No.${esc(r.number)} ${r.sample?'<span>示範短篇</span>':''}</p><h3>${esc(r.title)}</h3>${r.images?.length?`<img class="record-thumbnail" src="${esc(r.images[0].url)}" alt="${esc(r.title)}的封面" loading="lazy">`:''}<p class="record-summary">${esc(r.officialTitle)}<br>${esc(r.summary)}</p><div class="record-tags">${r.tags.map(t=>`<span>${esc(t)}</span>`).join('')}</div></div><a class="record-open" href="#read/${encodeURIComponent(r.id)}">OPEN FILE ↗</a></article>`).join('')||`<div class="empty-state"><p>${query||tag!=='全部'?'沒有符合的檔案，試著更換搜尋或標籤。':type==='漫畫'?'漫畫紀錄尚未公開。下一份追憶，仍在整理中。':type==='插畫'?'視覺紀錄尚未公開。插畫與塗鴉將在這裡歸檔。':'限制檔案尚未公開。'}</p></div>`;
 $('.tags').hidden=['人物','限制'].includes(type);
}
document.querySelectorAll('[data-type]').forEach(b=>b.onclick=()=>{type=b.dataset.type;tag='全部';document.querySelectorAll('[data-type]').forEach(x=>x.classList.toggle('active',x===b));document.querySelectorAll('[data-tag]').forEach(x=>x.classList.toggle('active',x.dataset.tag==='全部'));if(type==='限制')openDialog('<p class="eyebrow">RESTRICTED / CONTENT NOTICE</p><h2>限制檔案</h2><p>此分類可能包含成人暗示、黑暗情節及正篇劇透。請依個人接受程度選擇閱讀。</p><button class="button dark" id="acknowledge">了解，繼續瀏覽 →</button>');$('#acknowledge')?.addEventListener('click',()=>$('#dialog').close());render()});
document.querySelectorAll('[data-tag]').forEach(b=>b.onclick=()=>{tag=b.dataset.tag;document.querySelectorAll('[data-tag]').forEach(x=>x.classList.toggle('active',x===b));render()});
$('#search').oninput=render;
$('#random').onclick=()=>{const options=published().filter(r=>r.type==='小說'&&!r.restricted);if(options.length)location.hash='read/'+options[Math.floor(Math.random()*options.length)].id;else openDialog('<h2>沒有可抽選的短篇</h2><p>新的星期三仍在整理中。</p>')};
$('#systemLog').onclick=()=>openDialog('<p class="eyebrow">SYSTEM LOG / INFORMATION VALUE: NONE</p><h2>一個平常的早晨</h2><div class="log-lines">04:31　SUBJECT 01 離開寢室\n04:34　SUBJECT 01 前往訓練室\n07:52　SUBJECT 04 仍未起床\n09:17　SUBJECT 04 仍未起床\n10:46　SUBJECT 04 仍未起床\n11:32　SUBJECT 04 已讀訊息\n11:34　SUBJECT 01：「起床。」\n11:35　SUBJECT 04：「哥哥早安。」</div><p class="assessment">本紀錄之情報價值經重新評估為零。<br>非官方二次創作 / 示範紀錄</p>');
$('#openComic').onclick=()=>{const main=published().find(r=>r.mainComic);if(main)location.hash='read/'+main.id;else openDialog('<p class="eyebrow">FILE 041-C-001 / MAIN RECORD</p><h2>《追憶》尚未公開</h2><p>漫畫頁正在等待歸檔。公開後，可直接在這裡使用連續或單頁模式閱讀。</p><p>現在先去看看，那些尚未失去的星期三。</p><a href="#archive" class="button dark" id="toExtras">調閱番外紀錄 ↓</a>');$('#toExtras')?.addEventListener('click',()=>$('#dialog').close())};
function mediaView(r){const imgs=r.images||[];const visible=comicMode==='單頁'?[imgs[comicPage]]:imgs;return `<div class="comic-controls"><button data-mode="連續" class="${comicMode==='連續'?'active':''}">連續閱讀</button><button data-mode="單頁" class="${comicMode==='單頁'?'active':''}">單頁閱讀</button>${comicMode==='單頁'?`<button id="pagePrev" ${comicPage===0?'disabled':''}>← 上一頁</button><span class="media-caption">${comicPage+1} / ${imgs.length}</span><button id="pageNext" ${comicPage===imgs.length-1?'disabled':''}>下一頁 →</button>`:''}</div><div class="image-pages">${visible.filter(Boolean).map((m,i)=>`<img src="${esc(m.url)}" alt="${esc(r.title)}，第 ${comicMode==='單頁'?comicPage+1:i+1} 頁" ${i>0?'loading="lazy"':''}><p class="media-caption">PAGE ${comicMode==='單頁'?comicPage+1:i+1}</p>`).join('')}</div>`}
function bindMedia(){document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{comicMode=b.dataset.mode;updateMedia()});$('#pagePrev')?.addEventListener('click',()=>{comicPage--;updateMedia()});$('#pageNext')?.addEventListener('click',()=>{comicPage++;updateMedia()});}
function updateMedia(){$('#mediaReader').innerHTML=mediaView(current);bindMedia()}
function showReader(r){
 current=r;comicMode='連續';comicPage=0;$('#home').hidden=true;$('#reader').hidden=false;$('#readerContent').classList.toggle('comic-content',r.type!=='小說');
 $('#readerContent').innerHTML=`<p class="eyebrow">${r.type==='小說'?'INCIDENT RECORD':'VISUAL RECORD'} / No.${esc(r.number)}</p><h1>〈${esc(r.title)}〉</h1><p class="reader-meta">${esc(r.officialTitle)}<br>${r.tags.map(esc).join(' / ')}${r.sample?' · 示範短篇':''}<br>非官方二次創作 · 更新 ${esc((r.updated||'2026-10-01').slice(0,10))}</p>${r.type==='小說'?`<div class="prose">${prose(r.body)}</div>`:`<div id="mediaReader">${mediaView(r)}</div>${r.body?`<div class="prose">${prose(r.body)}</div>`:''}`}${r.assessment?`<div class="assessment"><span>OFFICIAL ASSESSMENT</span>${esc(r.assessment)}</div>`:''}`;
 const siblings=published().filter(x=>x.type===r.type&&!x.restricted);let i=siblings.findIndex(x=>x.id===r.id);$('#readerNav').innerHTML=`${i>0?`<a href="#read/${encodeURIComponent(siblings[i-1].id)}">← 上一篇</a>`:'<span></span>'}<a href="#archive">回到目錄</a>${i>=0&&i<siblings.length-1?`<a href="#read/${encodeURIComponent(siblings[i+1].id)}">下一篇 →</a>`:'<span></span>'}`;
 document.title=r.title+'｜41 王室機密檔案';bindMedia();window.scrollTo(0,0);try{if(localStorage.getItem('41-dark')==='1')document.body.classList.add('dark-mode')}catch{};progress();
}
function route(){const match=location.hash.match(/^#read\/(.+)$/);if(match){let id;try{id=decodeURIComponent(match[1])}catch{id=''}const r=published().find(x=>x.id===id);if(r){if(r.restricted){openDialog(`<p class="eyebrow">RESTRICTED FILE</p><h2>閱讀內容提示</h2><p>此篇包含成人暗示、黑暗情節或正篇劇透。是否繼續閱讀？</p><button id="continueRestricted" class="button dark">繼續閱讀 →</button><a class="button" href="#archive" id="leaveRestricted">返回目錄</a>`);$('#continueRestricted').onclick=()=>{$('#dialog').close();showReader(r)};$('#leaveRestricted').onclick=()=>$('#dialog').close()}else showReader(r);return;}openDialog('<h2>檔案未公開或不存在</h2><p>請回到目錄選擇其他作品。</p>');}current=null;$('#reader').hidden=true;$('#home').hidden=false;document.body.classList.remove('dark-mode');document.title='41｜卡金王室機密檔案';if(location.hash==='#archive')requestAnimationFrame(()=>$('#archive').scrollIntoView());}
window.addEventListener('hashchange',route);
function setFont(delta){fontSize=Math.min(26,Math.max(16,fontSize+delta));document.documentElement.style.setProperty('--font-size',fontSize+'px');try{localStorage.setItem('41-font',fontSize)}catch{}}
$('#fontDown').onclick=()=>setFont(-1);$('#fontUp').onclick=()=>setFont(1);$('#theme').onclick=()=>{document.body.classList.toggle('dark-mode');try{localStorage.setItem('41-dark',document.body.classList.contains('dark-mode')?'1':'0')}catch{}};
function progress(){if(!current)return;const max=document.documentElement.scrollHeight-innerHeight;$('#progressBar').style.width=(max>0?Math.min(100,scrollY/max*100):100)+'%'}window.addEventListener('scroll',progress,{passive:true});
async function load(){try{const res=await fetch('/api/records');if(!res.ok)throw Error();records=await res.json()}catch{records=await(await fetch('content.json')).json()}updateCounts();render();route()};load();
